        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the failure to properly handle errors when acquiring clock resources. Specifically, if the `devm_clk_get_optional` function returned an error (indicating that the clock resource could not be fetched), the code was returning the error code directly without freeing the previously allocated network device, leading to a potential memory leak.

        Commit message:
        net: systemport: free dev before on error path

On the error path, it should goto the error handling label to free
allocated memory rather than directly return.

Fixes: 31bc72d97656 ("net: systemport: fetch and use clock resources")
Signed-off-by: Pan Bian <bianpan2016@163.com>
Acked-by: Florian Fainelli <f.fainelli@gmail.com>
Link: https://lore.kernel.org/r/20210120044423.1704-1-bianpan2016@163.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>  

        Patch:

 static int bcm_sysport_probe(struct platform_device *pdev)
 {
 	const struct bcm_sysport_hw_params *params;
 	const struct of_device_id *of_id = NULL;
 	struct bcm_sysport_priv *priv;
 	struct device_node *dn;
 	struct net_device *dev;
 	const void *macaddr;
 	u32 txq, rxq;
 	int ret;

 	dn = pdev->dev.of_node;
 	of_id = of_match_node(bcm_sysport_of_match, dn);
 	if (!of_id || !of_id->data)
 		return -EINVAL;

 	ret = dma_set_mask_and_coherent(&pdev->dev, DMA_BIT_MASK(40));
 	if (ret)
 		ret = dma_set_mask_and_coherent(&pdev->dev, DMA_BIT_MASK(32));
 	if (ret) {
 		dev_err(&pdev->dev, "unable to set DMA mask: %d\n", ret);
 		return ret;
 	}

 	/* Fairly quickly we need to know the type of adapter we have */
 	params = of_id->data;

 	/* Read the Transmit/Receive Queue properties */
 	if (of_property_read_u32(dn, "systemport,num-txq", &txq))
 		txq = TDMA_NUM_RINGS;
 	if (of_property_read_u32(dn, "systemport,num-rxq", &rxq))
 		rxq = 1;

 	/* Sanity check the number of transmit queues */
 	if (!txq || txq > TDMA_NUM_RINGS)
 		return -EINVAL;

 	dev = alloc_etherdev_mqs(sizeof(*priv), txq, rxq);
 	if (!dev)
 		return -ENOMEM;

 	/* Initialize private members */
 	priv = netdev_priv(dev);

 	priv->clk = devm_clk_get_optional(&pdev->dev, "sw_sysport");
-	if (IS_ERR(priv->clk))
-		return PTR_ERR(priv->clk);
+	if (IS_ERR(priv->clk)) {
+		ret = PTR_ERR(priv->clk);
+		goto err_free_netdev;
+	}

 	/* Allocate number of TX rings */
 	priv->tx_rings = devm_kcalloc(&pdev->dev, txq,
 				      sizeof(struct bcm_sysport_tx_ring),
 				      GFP_KERNEL);
 	if (!priv->tx_rings) {
 		ret = -ENOMEM;
 		goto err_free_netdev;
 	}

 	priv->is_lite = params->is_lite;
 	priv->num_rx_desc_words = params->num_rx_desc_words;

 	priv->irq0 = platform_get_irq(pdev, 0);
 	if (!priv->is_lite) {
 		priv->irq1 = platform_get_irq(pdev, 1);
 		priv->wol_irq = platform_get_irq(pdev, 2);
 	} else {
 		priv->wol_irq = platform_get_irq(pdev, 1);
 	}
 	if (priv->irq0 <= 0 || (priv->irq1 <= 0 && !priv->is_lite)) {
 		ret = -EINVAL;
 		goto err_free_netdev;
 	}

 	priv->base = devm_platform_ioremap_resource(pdev, 0);
 	if (IS_ERR(priv->base)) {
 		ret = PTR_ERR(priv->base);
 		goto err_free_netdev;
 	}

 	priv->netdev = dev;
 	priv->pdev = pdev;

 	ret = of_get_phy_mode(dn, &priv->phy_interface);
 	/* Default to GMII interface mode */
 	if (ret)
 		priv->phy_interface = PHY_INTERFACE_MODE_GMII;

 	/* In the case of a fixed PHY, the DT node associated
 	 * to the PHY is the Ethernet MAC DT node.
 	 */
 	if (of_phy_is_fixed_link(dn)) {
 		ret = of_phy_register_fixed_link(dn);
 		if (ret) {
 			dev_err(&pdev->dev, "failed to register fixed PHY\n");
 			goto err_free_netdev;
 		}

 		priv->phy_dn = dn;
 	}

 	/* Initialize netdevice members */
 	macaddr = of_get_mac_address(dn);
 	if (IS_ERR(macaddr)) {
 		dev_warn(&pdev->dev, "using random Ethernet MAC\n");
 		eth_hw_addr_random(dev);
 	} else {
 		ether_addr_copy(dev->dev_addr, macaddr);
 	}

 	SET_NETDEV_DEV(dev, &pdev->dev);
 	dev_set_drvdata(&pdev->dev, dev);
 	dev->ethtool_ops = &bcm_sysport_ethtool_ops;
 	dev->netdev_ops = &bcm_sysport_netdev_ops;
 	netif_napi_add(dev, &priv->napi, bcm_sysport_poll, 64);

 	dev->features |= NETIF_F_RXCSUM | NETIF_F_HIGHDMA |
 			 NETIF_F_IP_CSUM | NETIF_F_IPV6_CSUM |
 			 NETIF_F_HW_VLAN_CTAG_TX;
 	dev->hw_features |= dev->features;
 	dev->vlan_features |= dev->features;
 	dev->max_mtu = UMAC_MAX_MTU_SIZE;

 	/* Request the WOL interrupt and advertise suspend if available */
 	priv->wol_irq_disabled = 1;
 	ret = devm_request_irq(&pdev->dev, priv->wol_irq,
 			       bcm_sysport_wol_isr, 0, dev->name, priv);
 	if (!ret)
 		device_set_wakeup_capable(&pdev->dev, 1);

 	priv->wol_clk = devm_clk_get_optional(&pdev->dev, "sw_sysportwol");
 	if (IS_ERR(priv->wol_clk))
 		return PTR_ERR(priv->wol_clk);

 	/* Set the needed headroom once and for all */
 	BUILD_BUG_ON(sizeof(struct bcm_tsb) != 8);
 	dev->needed_headroom += sizeof(struct bcm_tsb);

 	/* libphy will adjust the link state accordingly */
 	netif_carrier_off(dev);

 	priv->rx_max_coalesced_frames = 1;
 	u64_stats_init(&priv->syncp);

 	priv->dsa_notifier.notifier_call = bcm_sysport_dsa_notifier;

 	ret = register_dsa_notifier(&priv->dsa_notifier);
 	if (ret) {
 		dev_err(&pdev->dev, "failed to register DSA notifier\n");
 		goto err_deregister_fixed_link;
 	}

 	ret = register_netdev(dev);
 	if (ret) {
 		dev_err(&pdev->dev, "failed to register net_device\n");
 		goto err_deregister_notifier;
 	}

 	clk_prepare_enable(priv->clk);

 	priv->rev = topctrl_readl(priv, REV_CNTL) & REV_MASK;
 	dev_info(&pdev->dev,
 		 "Broadcom SYSTEMPORT%s " REV_FMT
 		 " (irqs: %d, %d, TXQs: %d, RXQs: %d)\n",
 		 priv->is_lite ? " Lite" : "",
 		 (priv->rev >> 8) & 0xff, priv->rev & 0xff,
 		 priv->irq0, priv->irq1, txq, rxq);

 	clk_disable_unprepare(priv->clk);

 	return 0;

 err_deregister_notifier:
 	unregister_dsa_notifier(&priv->dsa_notifier);
 err_deregister_fixed_link:
 	if (of_phy_is_fixed_link(dn))
 		of_phy_deregister_fixed_link(dn);
 err_free_netdev:
 	free_netdev(dev);
 	return ret;
 }



